@classmethod
def from_file(cls, path: str) -> "Redactor":
    """Load ``label=regex`` lines (``#`` comments allowed) and merge with defaults."""
    patterns: Dict[str, str] = {}
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            label, _, pattern = line.partition("=")
            if not pattern:
                raise ConfigError("redaction pattern file needs 'label=regex' lines: {0}".format(path))
            patterns[label.strip()] = pattern
    return cls(patterns)

def redact(self, text: str) -> RedactedText:
    mapping: Dict[str, str] = {}
    reverse: Dict[str, str] = {}
    counts: Dict[str, int] = {}
    counter = 0

    def replace(match: "re.Match[str]", label: str) -> str:
        nonlocal counter
        value = match.group(0)
        existing = reverse.get(value)
        if existing:
            return existing
        counter += 1
        placeholder = self._placeholder.format(label=label.upper(), index=counter)
        mapping[placeholder] = value
        reverse[value] = placeholder
        counts[label] = counts.get(label, 0) + 1
        return placeholder

